package com.codeguardian.controller; import com.codeguardian.service.SystemConfigService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/settings") @RequiredArgsConstructor public class SystemConfigController{private final SystemConfigService service;@GetMapping public Map<String,String> all(){return service.all();}@PutMapping public Map<String,String> update(@RequestBody Map<String,String> settings){return service.save(settings);}}@Controller class SettingsPageController{@GetMapping("/settings")String page(){return "settings";}}
